using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using NWD.EditorTools;
namespace NWD.EditorTools { public static class UnityRebuildBootstrap { static readonly string[] Nodes={"campaign-intro","lvl01-esc01-comedor-resistencia","lvl01-esc02-pasillos-hacia-escaleras-pb","lvl01-cin01-cierre-contextual"};
 [MenuItem("NWD/Bootstrap Unity Rebuild")]public static void Run(){try{RequirePackages();CanonicalCampaignImporter.Import();CreateScene("Assets/NWD/Scenes/Bootstrap/Bootstrap.unity",false);CreateScene("Assets/NWD/Scenes/Persistent/Persistent.unity",false);foreach(var node in Nodes)CreateScene($"Assets/NWD/Scenes/Campaign/{node}.unity",true);EditorBuildSettings.scenes=new[]{"Assets/NWD/Scenes/Bootstrap/Bootstrap.unity","Assets/NWD/Scenes/Persistent/Persistent.unity"}.Concat(Nodes.Select(n=>$"Assets/NWD/Scenes/Campaign/{n}.unity")).Select(p=>new EditorBuildSettingsScene(p,true)).ToArray();AssetDatabase.SaveAssets();Debug.Log("NWD bootstrap complete. Bake NavMesh surfaces and run tests before Play Mode.");}catch(Exception e){Debug.LogException(e);throw;}}
 static void RequirePackages(){var m=File.ReadAllText("Packages/manifest.json");foreach(var p in new[]{"render-pipelines.universal","inputsystem","cinemachine","ai.navigation","addressables","netcode.gameobjects","transport","test-framework"})if(!m.Contains(p))throw new InvalidDataException("Missing package: "+p);}
 static void CreateScene(string path,bool greybox){var scene=File.Exists(path)?EditorSceneManager.OpenScene(path,OpenSceneMode.Single):EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);if(!GameObject.Find("NWD_SceneRoot")){var root=new GameObject("NWD_SceneRoot");if(greybox){var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="Greybox_Floor";floor.transform.SetParent(root.transform);floor.transform.localScale=new Vector3(30,.2f,30);var light=new GameObject("Provisional_Light").AddComponent<Light>();light.type=LightType.Directional;light.transform.SetParent(root.transform);new GameObject("PlayerSpawn").transform.SetParent(root.transform);new GameObject("SquadSpawns").transform.SetParent(root.transform);new GameObject("ObjectiveVolume").transform.SetParent(root.transform);new GameObject("InfectedSpawns").transform.SetParent(root.transform);}}Directory.CreateDirectory(Path.GetDirectoryName(path));EditorSceneManager.SaveScene(scene,path);}
 }}
